export const BUILTIN_AGENT_PROFILES = [
    {
        command: ['codex'],
        modelArgument: '--model',
        models: ['gpt-5.5', 'gpt-5.6-sol', 'gpt-5.6-terra', 'gpt-5.6-luna'],
